// Runtime support for the 'binsearch' CFI check variant.
// Compiled to bitcode and linked with the instrumented program AFTER the
// pass has run (so the pass does not instrument/analyse this code).
#include <stdint.h>
#include <stdlib.h>

static int cmp_addr(const void *a, const void *b) {
  uintptr_t x = *(const uintptr_t *)a, y = *(const uintptr_t *)b;
  return (x > y) - (x < y);
}

// Called once per table by the constructor generated by the pass:
// sorts the table of allowed targets by address (addresses are only known
// at load time because of PIE/ASLR).
void __cfi_sort(uintptr_t *tab, unsigned n) {
  qsort(tab, n, sizeof(uintptr_t), cmp_addr);
}

// Binary search (lower bound) in the sorted table.
// Returns 1 if p is in the table, 0 otherwise.
// always_inline: the final -O2 compile inlines it at every call site, so
// we measure the check itself and not the cost of a function call.
__attribute__((always_inline))
int __cfi_check_bs(const uintptr_t *tab, unsigned n, uintptr_t p) {
  unsigned lo = 0, hi = n;
  while (lo < hi) {
    unsigned mid = lo + (hi - lo) / 2;
    if (tab[mid] < p)
      lo = mid + 1;
    else
      hi = mid;
  }
  return lo < n && tab[lo] == p;
}
